      color: #FFFFFF;
      text-decoration: underline;
      text-underline-offset: 2px;
    }

    .cookie-banner-text a:hover {
      color: #EB0028;
    }

    .cookie-banner-actions {
      display: flex;
      align-items: center;
      gap: 12px;
      flex-shrink: 0;
    }

    .btn-manage {
      padding: 10px 20px;
      font-size: 0.85rem;
      font-family: inherit;
      font-weight: 500;
      border: 1.5px solid #FFFFFF;
      border-radius: 6px;
      background: transparent;
      color: #FFFFFF;
      cursor: pointer;
      white-space: nowrap;
      transition: background-color 0.2s ease, color 0.2s ease;
    }

    .btn-manage:hover {
      background: #FFFFFF;
      color: #1A1A1A;
    }

    .btn-manage:focus-visible {
      outline: 2px solid #EB0028;
      outline-offset: 2px;
    }

    /* Cookie modal overlay */
    .modal-overlay {
      position: fixed;
      inset: 0;
      background: rgba(0, 0, 0, 0.5);
