        e.preventDefault();
        var query = searchInput.value.trim();
        if (query) {
          window.location.href = '/search?q=' + encodeURIComponent(query);
        }
      });

      function openModal() {
        prefsModal.classList.add('active');
        document.body.style.overflow = 'hidden';
        modalCloseBtn.focus();
      }

      function closeModal() {
        prefsModal.classList.remove('active');
        document.body.style.overflow = '';
        managePrefsBtn.focus();
      }

      function dismissBanner() {
        cookieBanner.classList.add('hidden');
      }

      managePrefsBtn.addEventListener('click', openModal);
      modalCloseBtn.addEventListener('click', closeModal);

      prefsModal.addEventListener('click', function(e) {
        if (e.target === prefsModal) closeModal();
      });

      document.addEventListener('keydown', function(e) {
        if (e.key === 'Escape' && prefsModal.classList.contains('active')) {
          closeModal();
        }
      });

      savePrefsBtn.addEventListener('click', function() {
        closeModal();
        dismissBanner();
      });
    })();
  </script>

